    "percorso": "options_menu.gd",
    "contenuto": "extends Control

@onready var master_slider: HSlider = $VBoxContainer/MasterSlider
@onready var music_slider: HSlider = $VBoxContainer/MusicSlider
@onready var sfx_slider: HSlider = $VBoxContainer/SFXSlider
@onready var mute_button: CheckButton = $VBoxContainer/MuteButton
@onready var reset_button: Button = $VBoxContainer/ResetButton
@onready var back_button: Button = $VBoxContainer/BackButton

var _master_bus_idx: int = 0
var _music_bus_idx: int = 0
var _sfx_bus_idx: int = 0


func _ready() -> void:
	_master_bus_idx = AudioServer.get_bus_index("Master")
	_music_bus_idx = AudioServer.get_bus_index("Music")
	_sfx_bus_idx = AudioServer.get_bus_index("SFX")

	master_slider.min_value = 0.0001
	master_slider.max_value = 1.0
	master_slider.step = 0.01

	music_slider.min_value = 0.0001
	music_slider.max_value = 1.0
	music_slider.step = 0.01

	sfx_slider.min_value = 0.0001
	sfx_slider.max_value = 1.0
	sfx_slider.step = 0.01

	if FileAccess.file_exists("user://settings.json"):
		load_audio_settings()
	else:
		_sync_ui_from_audio_server()

	master_slider.value_changed.connect(_on_master_slider_value_changed)
	music_slider.value_changed.connect(_on_music_slider_value_changed)
	sfx_slider.value_changed.connect(_on_sfx_slider_value_changed)
	mute_button.toggled.connect(_on_mute_button_toggled)
	reset_button.pressed.connect(_on_reset_button_pressed)
	back_button.pressed.connect(_on_back_button_pressed)


func _sync_ui_from_audio_server() -> void:
	if _master_bus_idx >= 0:
		master_slider.value = db_to_linear(AudioServer.get_bus_volume_db(_master_bus_idx))
		mute_button.button_pressed = AudioServer.is_bus_mute(_master_bus_idx)
	if _music_bus_idx >= 0:
		music_slider.value = db_to_linear(AudioServer.get_bus_volume_db(_music_bus_idx))
	if _sfx_bus_idx >= 0:
		sfx_slider.value = db_to_linear(AudioServer.get_bus_volume_db(_sfx_bus_idx))


func _on_master_slider_value_changed(value: float) -> void:
	if _master_bus_idx >= 0:
		AudioServer.set_bus_volume_db(_master_bus_idx, linear_to_db(value))
		save_audio_settings()


func _on_music_slider_value_changed(value: float) -> void:
	if _music_bus_idx >= 0:
		AudioServer.set_bus_volume_db(_music_bus_idx, linear_to_db(value))
		save_audio_settings()


func _on_sfx_slider_value_changed(value: float) -> void:
	if _sfx_bus_idx >= 0:
		AudioServer.set_bus_volume_db(_sfx_bus_idx, linear_to_db(value))
		save_audio_settings()


func _on_mute_button_toggled(toggled_on: bool) -> void:
	if _master_bus_idx >= 0:
		AudioServer.set_bus_mute(_master_bus_idx, toggled_on)
		save_audio_settings()


func _on_reset_button_pressed() -> void:
	master_slider.value = 1.0
	music_slider.value = 1.0
	sfx_slider.value = 1.0
	mute_button.button_pressed = false

	if _master_bus_idx >= 0:
		AudioServer.set_bus_volume_db(_master_bus_idx, linear_to_db(1.0))
		AudioServer.set_bus_mute(_master_bus_idx, false)
	if _music_bus_idx >= 0:
		AudioServer.set_bus_volume_db(_music_bus_idx, linear_to_db(1.0))
	if _sfx_bus_idx >= 0:
		AudioServer.set_bus_volume_db(_sfx_bus_idx, linear_to_db(1.0))

	save_audio_settings()


func _on_back_button_pressed() -> void:
	get_tree().change_scene_to_file("res://menu.tscn")


func save_audio_settings() -> void:
	var settings_data: Dictionary = {
		"master_volume": master_slider.value,
		"music_volume": music_slider.value,
		"sfx_volume": sfx_slider.value,
		"is_muted": mute_button.button_pressed
	}
	var json_string: String = JSON.stringify(settings_data)
	var file: FileAccess = FileAccess.open("user://settings.json", FileAccess.WRITE)
	if file != null:
		file.store_string(json_string)


func load_audio_settings() -> void:
	if not FileAccess.file_exists("user://settings.json"):
		return

	var file: FileAccess = FileAccess.open("user://settings.json", FileAccess.READ)
	if file == null:
		return

	var content: String = file.get_as_text()
	var json: JSON = JSON.new()
	if json.parse(content) != OK:
		return

	if not (json.data is Dictionary):
		return

	var data: Dictionary = json.data

	if data.has("master_volume"):
		var val: float = maxf(0.0001, float(data["master_volume"]))
		master_slider.value = val
		if _master_bus_idx >= 0:
			AudioServer.set_bus_volume_db(_master_bus_idx, linear_to_db(val))

	if data.has("music_volume"):
		var val: float = maxf(0.0001, float(data["music_volume"]))
		music_slider.value = val
		if _music_bus_idx >= 0:
			AudioServer.set_bus_volume_db(_music_bus_idx, linear_to_db(val))

	if data.has("sfx_volume"):
		var val: float = maxf(0.0001, float(data["sfx_volume"]))
		sfx_slider.value = val
		if _sfx_bus_idx >= 0:
			AudioServer.set_bus_volume_db(_sfx_bus_idx, linear_to_db(val))

	if data.has("is_muted"):
		var muted: bool = bool(data["is_muted"])
		mute_button.button_pressed = muted
		if _master_bus_idx >= 0:
			AudioServer.set_bus_mute(_master_bus_idx, muted)
