    "percorso": "quiz_data.gd",
    "contenuto": "extends Node

var score: int = 0
var high_score: int = 0
var current_topic_title: String = ""
var topic_records: Dictionary = {}

var master_volume: float = 1.0
var music_volume: float = 0.8
var sfx_volume: float = 0.8

const SETTINGS_PATH := "user://settings.json"


func _ready() -> void:
	_ensure_audio_buses()
	load_settings()


func _ensure_audio_buses() -> void:
	if AudioServer.get_bus_index("Music") == -1:
		AudioServer.add_bus()
		var music_idx := AudioServer.get_bus_count() - 1
		AudioServer.set_bus_name(music_idx, "Music")
	if AudioServer.get_bus_index("SFX") == -1:
		AudioServer.add_bus()
		var sfx_idx := AudioServer.get_bus_count() - 1
		AudioServer.set_bus_name(sfx_idx, "SFX")


func set_bus_volume(bus_name: String, value: float) -> void:
	var idx := AudioServer.get_bus_index(bus_name)
	if idx == -1:
		return
	var clamped_val := clampf(value, 0.0, 1.0)
	if bus_name == "Master":
		master_volume = clamped_val
	elif bus_name == "Music":
		music_volume = clamped_val
	elif bus_name == "SFX":
		sfx_volume = clamped_val

	if clamped_val <= 0.0001:
		AudioServer.set_bus_mute(idx, true)
	else:
		AudioServer.set_bus_mute(idx, false)
		AudioServer.set_bus_volume_db(idx, linear_to_db(clamped_val))


func save_settings() -> void:
	var data := {
		"master": master_volume,
		"music": music_volume,
		"sfx": sfx_volume
	}
	var file := FileAccess.open(SETTINGS_PATH, FileAccess.WRITE)
	if file != null:
		file.store_string(JSON.stringify(data, "\t"))
		file.close()


func load_settings() -> void:
	if not FileAccess.file_exists(SETTINGS_PATH):
		save_settings()
		return
	var file := FileAccess.open(SETTINGS_PATH, FileAccess.READ)
	if file == null:
		return
	var text := file.get_as_text()
	file.close()
	var json := JSON.new()
	if json.parse(text) == OK and typeof(json.data) == TYPE_DICTIONARY:
		var dict: Dictionary = json.data
		master_volume = float(dict.get("master", 1.0))
		music_volume = float(dict.get("music", 0.8))
		sfx_volume = float(dict.get("sfx", 0.8))

	set_bus_volume("Master", master_volume)
	set_bus_volume("Music", music_volume)
	set_bus_volume("SFX", sfx_volume)
"
