    "contenuto": "extends Control

@onready var credits_container: VBoxContainer = $CenterContainer/VBoxContainer/CreditsListContainer
@onready var back_button: Button = $CenterContainer/VBoxContainer/BackButton


func _ready() -> void:
	back_button.pressed.connect(_on_back_pressed)
	load_credits()


func load_credits() -> void:
	var path := "res://credits.json"
	if not FileAccess.file_exists(path):
		var err_lbl := Label.new()
		err_lbl.text = "File crediti non trovato."
		credits_container.add_child(err_lbl)
		return

	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		return
	var text := file.get_as_text()
	file.close()

	var json := JSON.new()
	if json.parse(text) != OK or typeof(json.data) != TYPE_ARRAY:
		var err_lbl := Label.new()
		err_lbl.text = "Errore nella lettura dei crediti."
		credits_container.add_child(err_lbl)
		return

	var entries: Array = json.data
	for item in entries:
		if typeof(item) == TYPE_DICTIONARY:
			var asset_name: String = str(item.get("asset", "Asset"))
			var author: String = str(item.get("author", "Autore sconosciuto"))
			var license: String = str(item.get("license", "Licenza non specificata"))

			var lbl := Label.new()
			lbl.text = "%s — %s (%s)" % [asset_name, author, license]
			lbl.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
			credits_container.add_child(lbl)


func _on_back_pressed() -> void:
	get_tree().change_scene_to_file("res://menu.tscn")
