    "percorso": "quiz.gd",
    "contenuto": "extends Control

@onready var question_timer: Timer = $QuestionTimer
@onready var time_bar: ProgressBar = $MarginContainer/VBoxContainer/TimeBar
@onready var question_label: Label = $MarginContainer/VBoxContainer/QuestionPanel/QuestionLabel
@onready var answers_container: VBoxContainer = $MarginContainer/VBoxContainer/AnswersContainer
@onready var pause_menu: ColorRect = $PauseMenu
@onready var resume_button: Button = $PauseMenu/CenterContainer/PausePanel/VBoxContainer/ResumeButton
@onready var quit_button: Button = $PauseMenu/CenterContainer/PausePanel/VBoxContainer/QuitButton

@onready var correct_sfx: AudioStreamPlayer = $CorrectSFX
@onready var wrong_sfx: AudioStreamPlayer = $WrongSFX

var session: QuizSession
var current_topic: QuizTopic


func _ready() -> void:
	current_topic = load("res://general_knowledge.tres") as QuizTopic
	if current_topic != null:
		QuizData.current_topic_title = current_topic.title
		session = QuizSession.new(current_topic.questions)
	else:
		session = QuizSession.new([])

	question_timer.timeout.connect(_on_timer_timeout)
	resume_button.pressed.connect(_toggle_pause)
	quit_button.pressed.connect(_on_quit_pressed)

	_bind_answer_buttons()
	_show_current_question()


func _process(_delta: float) -> void:
	if not question_timer.is_stopped():
		time_bar.value = question_timer.time_left


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("pause"):
		_toggle_pause()


func _bind_answer_buttons() -> void:
	var buttons := answers_container.get_children()
	for i in range(buttons.size()):
		var btn := buttons[i] as Button
		if btn != null:
			var idx := i
			btn.pressed.connect(func() -> void: _on_answer_selected(idx))


func _show_current_question() -> void:
	if session == null or session.is_finished():
		_finish_quiz()
		return

	var q: Question = session.get_current_question()
	if q == null:
		_finish_quiz()
		return

	question_label.text = q.text
	var buttons := answers_container.get_children()
	for i in range(buttons.size()):
		var btn := buttons[i] as Button
		if btn != null:
			if i < q.options.size():
				btn.text = q.options[i]
				btn.visible = true
			else:
				btn.visible = false

	question_timer.start(5.0)
	time_bar.max_value = 5.0
	time_bar.value = 5.0


func _on_answer_selected(index: int) -> void:
	if session == null or session.is_finished():
		return

	question_timer.stop()
	var is_correct: bool = session.submit_answer(index)
	if is_correct:
		if correct_sfx:
			correct_sfx.play()
	else:
		if wrong_sfx:
			wrong_sfx.play()

	session.advance()
	_show_current_question()


func _on_timer_timeout() -> void:
	if session == null or session.is_finished():
		return

	session.submit_answer(-1)
	if wrong_sfx:
		wrong_sfx.play()
	session.advance()
	_show_current_question()


func _finish_quiz() -> void:
	QuizData.score = session.score if session != null else 0
	if QuizData.score > QuizData.high_score:
		QuizData.high_score = QuizData.score

	if current_topic != null and current_topic.title != "":
		var prev_rec: int = int(QuizData.topic_records.get(current_topic.title, 0))
		if QuizData.score > prev_rec:
			QuizData.topic_records[current_topic.title] = QuizData.score

	get_tree().change_scene_to_file("res://results.tscn")


func _toggle_pause() -> void:
	var paused: bool = not get_tree().paused
	get_tree().paused = paused
	pause_menu.visible = paused


func _on_quit_pressed() -> void:
	get_tree().paused = false
	get_tree().change_scene_to_file("res://menu.tscn")
